        let sm: [ChargeSample] = cs.flatMap { $0.samples ?? [] }.filter { $0.soc != nil && $0.kw > 0.5 }
        let parTranche: [Int: [ChargeSample]] = Dictionary(grouping: sm) { Int(($0.soc ?? 0) / 5) * 5 }
        return parTranche.keys.sorted().map { (k: Int) -> Pt in
            let v: [ChargeSample] = parTranche[k] ?? []
            let somme: Double = v.map(\.kw).reduce(0, +)
            return Pt(lieu: l, soc: Double(k) + 2.5, kw: somme / Double(max(v.count, 1)))
        }
    }
    private var courbes: [Pt] {
        let top = groupes.sorted { $0.value.count > $1.value.count }.prefix(5)
        return top.flatMap { Self.courbe($0.key, $0.value) }
    }


